INSERT INTO public.quizzes (id, title, subject, grade, questions, created_by, is_published, description, quiz_type, difficulty_level, time_limit_minutes, passing_score_percentage, total_questions, allow_retakes, show_answers_after_submission, tags, metadata)
SELECT id, title, subject, grade, questions, created_by, is_published, description, quiz_type, difficulty_level, time_limit_minutes, passing_score_percentage, total_questions, allow_retakes, show_answers_after_submission, tags, metadata FROM jsonb_populate_recordset(NULL::public.quizzes, $smartbridge$[{"id":"da6e9227-744b-5308-9973-b93047e696bf","title":"Life Orientation · Grade 12 · Term 2: Media literacy, rights and civic participation","subject":"Life Orientation","grade":"Grade 12","questions":[{"question":"A news post shows a dramatic claim without a date or source. What should a learner do before sharing?","options":["Share because the headline is emotional","Verify the original source, date, context and supporting evidence","Assume every image is current","Replace verification with the number of likes"],"correct_index":1,"explanation":"Media literacy includes source evaluation and context. Old or altered material can mislead even when it appears convincing."},{"question":"Why is freedom of expression linked to responsibility?","options":["It permits any harassment without consequence","It means only one view may exist","Expression can affect others' rights and requires consideration of lawful limits and harm","It removes every duty to check facts"],"correct_index":2,"explanation":"Rights operate alongside other rights and responsibilities. Use accurate information and respectful debate rather than threats or discrimination."},{"question":"Which is meaningful participation in a local environmental issue?","options":["Invent survey results","Exclude residents most affected","Assume a viral post alone solves the problem","Gather reliable information, consult affected people and engage relevant decision-makers"],"correct_index":3,"explanation":"Effective participation combines evidence, inclusion and follow-through. Evaluate whether actions lead to practical changes."},{"question":"How can media representation reinforce stereotypes?","options":["Repeated narrow portrayals can make unfair generalisations seem normal","Every repeated portrayal is automatically accurate","Only written media influences perceptions","Representation has no effect on audiences"],"correct_index":0,"explanation":"Analyse whose voices appear, who is omitted and how groups are framed. Compare portrayals with varied evidence and lived experiences."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Media literacy, rights and civic participation. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","lo"],"metadata":{"term":2,"focus":"Media literacy, rights and civic participation","language":"en","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=dKf4zpe-LJ0%3d&tabid=3205&portalid=0&mid=10755","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=aovsPAsVZao%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/lo-12","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"41953fb6-1781-5f71-a703-8be904d050e4","title":"Life Orientation · Grade 12 · Term 3: Workplace choices, contracts and ethics","subject":"Life Orientation","grade":"Grade 12","questions":[{"question":"Before accepting a job, what should a learner clarify?","options":["Only the colour of the office","Whether the employer avoids every written record","Duties, pay, hours, conditions and the legitimacy of the employer","Whether friends like the logo"],"correct_index":2,"explanation":"Read and understand employment terms and verify the opportunity. Seek qualified help if terms are unclear or concerning."},{"question":"Why is equity different from treating everyone identically?","options":["Equity means ignoring discrimination","Equity requires identical support regardless of need","Equity removes all performance expectations","Fair access may require addressing different barriers and support needs"],"correct_index":3,"explanation":"Equity focuses on fair opportunity and participation, which may involve targeted support or accommodation."},{"question":"A worker notices a safety hazard outside their training. What is the responsible response?","options":["Report it through appropriate channels and avoid unsafe untrained action","Try a dangerous repair alone","Hide it to appear efficient","Encourage others to ignore it"],"correct_index":0,"explanation":"Safety includes recognising limits, following procedures and alerting responsible people. Work ethic does not require taking avoidable risks."},{"question":"What is a sound response to a request to falsify a workplace record?","options":["Change it because instructions remove responsibility","Refuse falsification and seek appropriate guidance or reporting support","Delete all evidence immediately","Ask a friend to invent the details"],"correct_index":1,"explanation":"Honesty and accountability apply even under pressure. Use suitable procedures and support while considering personal safety and context."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Workplace choices, contracts and ethics. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","lo"],"metadata":{"term":3,"focus":"Workplace choices, contracts and ethics","language":"en","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=dKf4zpe-LJ0%3d&tabid=3205&portalid=0&mid=10755","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=aovsPAsVZao%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/lo-12","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"f0b80004-b7fb-55ed-b8fa-e04aec976689","title":"Life Orientation · Grade 12 · Term 4: Post-school planning and exam preparation","subject":"Life Orientation","grade":"Grade 12","questions":[{"question":"Why should a matric learner prepare more than one post-school option?","options":["A first choice is guaranteed once imagined","Alternatives mean abandoning ambition","All options have identical requirements","Admission, funding and opportunities may be uncertain"],"correct_index":3,"explanation":"A practical plan includes preferred and alternative routes, verified requirements, deadlines and funding options."},{"question":"What belongs on an honest entry-level CV?","options":["Relevant education, skills and experience described accurately","Invented qualifications","Another person's achievements","A guaranteed salary demand presented as a qualification"],"correct_index":0,"explanation":"School projects, volunteering and responsibilities can provide relevant evidence. Describe actual contributions and obtain permission for references where appropriate."},{"question":"A learner loses marks despite knowing the content. What should they review?","options":["Only handwriting colour","Instruction words, time allocation and how answers address the question","Assume every marker is unfair","Stop practising questions"],"correct_index":1,"explanation":"Exam technique complements knowledge. Practise interpreting commands, structuring answers and allocating time, then use feedback to improve."},{"question":"Why record bursary and application deadlines in a plan?","options":["Every bursary stays open permanently","A reminder automatically submits an application","Different opportunities have different requirements and closing dates","Only the year matters"],"correct_index":2,"explanation":"Track exact deadlines and required documents, and verify the official notice. Planning and reminders support action but do not replace submitting a complete application."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Post-school planning and exam preparation. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","lo"],"metadata":{"term":4,"focus":"Post-school planning and exam preparation","language":"en","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=dKf4zpe-LJ0%3d&tabid=3205&portalid=0&mid=10755","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=aovsPAsVZao%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/lo-12","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"3b153d84-dd53-5ad4-8fe5-d9b30e0340fa","title":"English HL · Grade 12 · Term 2: Evaluating evidence and qualified conclusions","subject":"English HL","grade":"Grade 12","questions":[{"question":"What is the main weakness in the newsletter's causal claim?","options":["A higher pass rate can never be measured","Tutoring cannot possibly help anyone","Other changes may also explain the higher pass rate","Newsletters contain no useful information"],"correct_index":2,"explanation":"Without an appropriate comparison, concurrent changes make it difficult to isolate tutoring's effect. This limits the causal claim without proving the programme ineffective.","stimulus":"After a school introduced evening tutoring, its pass rate rose. The newsletter credited the programme. However, the year also saw smaller classes and a change in the learners enrolled. The report did not compare similar groups."},{"question":"Which statement is best supported?","options":["Tutoring alone caused the entire rise.","Smaller classes had no possible influence.","Every learner benefited by the same amount.","Pass rates rose after tutoring began, but the programme's independent effect is uncertain."],"correct_index":3,"explanation":"The cautious conclusion distinguishes sequence and association from established causation.","stimulus":"After a school introduced evening tutoring, its pass rate rose. The newsletter credited the programme. However, the year also saw smaller classes and a change in the learners enrolled. The report did not compare similar groups."},{"question":"What role does However play?","options":["It introduces a qualification to the preceding explanation","It adds an unrelated example","It confirms the causal claim without reservation","It marks a direct quotation"],"correct_index":0,"explanation":"The connector signals contrasting evidence that complicates the initial explanation. Track relationships between sentences, not only individual facts.","stimulus":"After a school introduced evening tutoring, its pass rate rose. The newsletter credited the programme. However, the year also saw smaller classes and a change in the learners enrolled. The report did not compare similar groups."},{"question":"Which additional evidence would most strengthen evaluation?","options":["A second slogan praising the programme","A well-designed comparison accounting for class size and learner differences","More copies of the same newsletter","A promise to avoid collecting data"],"correct_index":1,"explanation":"Comparable groups and attention to alternative explanations help test the claim. No single method removes every limitation, so assess design quality.","stimulus":"After a school introduced evening tutoring, its pass rate rose. The newsletter credited the programme. However, the year also saw smaller classes and a change in the learners enrolled. The report did not compare similar groups."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Evaluating evidence and qualified conclusions. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","enhl"],"metadata":{"term":2,"focus":"Evaluating evidence and qualified conclusions","language":"en","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=DyjByGE3HzY%3d&tabid=3205&portalid=0&mid=10756","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=WtjOh8RBcU0%3d&tabid=570&portalid=0&mid=1555","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/enhl-12","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"b8198f41-1bcc-5b65-9f40-1723f03090c3","title":"English HL · Grade 12 · Term 3: Framing, omission and persuasive revision","subject":"English HL","grade":"Grade 12","questions":[{"question":"What is the effect of Lazy in the headline?","options":["It is a neutral measure of motivation","It proves every learner's attitude","It supplies a transport timetable","It frames learners negatively before their circumstances are examined"],"correct_index":3,"explanation":"The loaded label guides judgment without establishing motives. Critical reading separates description from evaluation and evidence.","stimulus":"The headline read: Lazy learners abandon the reading room. The article mentioned empty chairs but omitted interviews with learners who lacked evening transport. Its photograph showed a half-empty room taken before opening time."},{"question":"Why does the photograph's timing matter?","options":["It may misleadingly suggest low attendance during operating hours","Any photograph proves the headline","Timing never affects visual evidence","It makes interviews unnecessary"],"correct_index":0,"explanation":"A pre-opening image is not reliable evidence of attendance while the room operates. Captions and context affect interpretation.","stimulus":"The headline read: Lazy learners abandon the reading room. The article mentioned empty chairs but omitted interviews with learners who lacked evening transport. Its photograph showed a half-empty room taken before opening time."},{"question":"Which omission most directly weakens the article's explanation?","options":["The brand of every chair","Learners' accounts of transport barriers","The writer's favourite novel","The room's wall colour"],"correct_index":1,"explanation":"Excluding relevant affected voices can narrow an explanation and conceal practical constraints. The omission matters because it relates directly to attendance.","stimulus":"The headline read: Lazy learners abandon the reading room. The article mentioned empty chairs but omitted interviews with learners who lacked evening transport. Its photograph showed a half-empty room taken before opening time."},{"question":"Which headline is more balanced?","options":["All learners refuse to work","Transport never affects attendance","Reading-room attendance raises questions about access","Empty chairs prove laziness"],"correct_index":2,"explanation":"The revised headline identifies the issue without assigning unsupported blame. Balanced wording still allows investigation and criticism.","stimulus":"The headline read: Lazy learners abandon the reading room. The article mentioned empty chairs but omitted interviews with learners who lacked evening transport. Its photograph showed a half-empty room taken before opening time."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Framing, omission and persuasive revision. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","enhl"],"metadata":{"term":3,"focus":"Framing, omission and persuasive revision","language":"en","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=DyjByGE3HzY%3d&tabid=3205&portalid=0&mid=10756","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=WtjOh8RBcU0%3d&tabid=570&portalid=0&mid=1555","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/enhl-12","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"f248231b-3b45-566d-89c5-d87bfe40433a","title":"English HL · Grade 12 · Term 4: Close reading and literary argument","subject":"English HL","grade":"Grade 12","questions":[{"question":"Which detail creates the clearest contrast?","options":["Noma steps away while others move forward","The letter has folds","The train reaches a station","There are other travellers"],"correct_index":0,"explanation":"The opposing movements foreground Noma's hesitation or different decision. Interpretation should connect this contrast to other details.","stimulus":"At the station, Noma unfolded the letter once more. The train arrived, impatient and bright. She put the letter in her pocket and stepped away from the platform's edge, while everyone else moved forward."},{"question":"What does impatient attribute to the train?","options":["A measured delay of exactly one hour","A human quality that intensifies urgency","A literal spoken complaint","Proof of mechanical failure"],"correct_index":1,"explanation":"Personification gives the train urgency and energy, contrasting with Noma's pause. The adjective does not establish a technical fault.","stimulus":"At the station, Noma unfolded the letter once more. The train arrived, impatient and bright. She put the letter in her pocket and stepped away from the platform's edge, while everyone else moved forward."},{"question":"Which interpretation remains appropriately qualified?","options":["The letter definitely contains a job rejection.","Noma has never travelled before.","The repeated reading and backward movement suggest uncertainty about departing.","The other travellers know the letter's contents."],"correct_index":2,"explanation":"The text supports hesitation but does not reveal the letter's content or full history. A defensible argument respects those limits.","stimulus":"At the station, Noma unfolded the letter once more. The train arrived, impatient and bright. She put the letter in her pocket and stepped away from the platform's edge, while everyone else moved forward."},{"question":"Which sentence best integrates evidence into an analytical claim?","options":["Noma is sad because all stations are sad.","The train is bright, so the letter is good news.","The passage proves that travel is always harmful.","Noma's movement away as others move forward dramatises her separation from their shared purpose."],"correct_index":3,"explanation":"The strongest claim connects a specific textual contrast to an interpreted effect without unsupported universal conclusions.","stimulus":"At the station, Noma unfolded the letter once more. The train arrived, impatient and bright. She put the letter in her pocket and stepped away from the platform's edge, while everyone else moved forward."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Close reading and literary argument. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","enhl"],"metadata":{"term":4,"focus":"Close reading and literary argument","language":"en","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=DyjByGE3HzY%3d&tabid=3205&portalid=0&mid=10756","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=WtjOh8RBcU0%3d&tabid=570&portalid=0&mid=1555","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/enhl-12","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"794842d3-e1d1-5970-920a-dbe53c48f98b","title":"Afrikaans HL · Grade 12 · Term 2: Bewyse en gekwalifiseerde gevolgtrekkings","subject":"Afrikaans HL","grade":"Grade 12","questions":[{"question":"Wat verswak die nuusbrief se oorsaaklike aanspraak?","options":["Slaagsyfers kan nooit gemeet word nie","Ekstra onderrig kan niemand help nie","Nuusbriewe bevat nooit feite nie","Ander veranderings kan ook die styging help verklaar"],"correct_index":3,"explanation":"Sonder 'n gepaste vergelyking is dit moeilik om die program se afsonderlike invloed te bepaal.","stimulus":"Nadat aandklasse begin het, styg 'n skool se slaagsyfer. Die nuusbrief skryf die styging aan die program toe. Klasse was egter ook kleiner en die leerdergroep het verander. Geen soortgelyke groepe is vergelyk nie."},{"question":"Watter gevolgtrekking word die beste ondersteun?","options":["Die slaagsyfer het gestyg, maar die program se afsonderlike effek is onseker.","Die program alleen het die hele styging veroorsaak.","Kleiner klasse het geen moontlike invloed nie.","Elke leerder het presies ewe veel gebaat."],"correct_index":0,"explanation":"Die versigtige gevolgtrekking onderskei tydsvolgorde en verband van bewese oorsaaklikheid.","stimulus":"Nadat aandklasse begin het, styg 'n skool se slaagsyfer. Die nuusbrief skryf die styging aan die program toe. Klasse was egter ook kleiner en die leerdergroep het verander. Geen soortgelyke groepe is vergelyk nie."},{"question":"Wat is die funksie van egter?","options":["Dit bevestig die aanspraak sonder voorbehoud","Dit kwalifiseer die voorafgaande verklaring","Dit begin 'n direkte aanhaling","Dit voeg 'n onverwante resep by"],"correct_index":1,"explanation":"Egter lei teenstellende inligting in wat die eerste verklaring ingewikkelder maak.","stimulus":"Nadat aandklasse begin het, styg 'n skool se slaagsyfer. Die nuusbrief skryf die styging aan die program toe. Klasse was egter ook kleiner en die leerdergroep het verander. Geen soortgelyke groepe is vergelyk nie."},{"question":"Watter ondersoek sal die evaluering versterk?","options":["Nog kopieë van dieselfde slagspreuk","Slegs 'n groter foto","'n Goed ontwerpte vergelyking wat ander verskille in ag neem","Die uitsluiting van alle data"],"correct_index":2,"explanation":"Vergelykbare groepe en aandag aan alternatiewe verklarings help om die aanspraak te toets.","stimulus":"Nadat aandklasse begin het, styg 'n skool se slaagsyfer. Die nuusbrief skryf die styging aan die program toe. Klasse was egter ook kleiner en die leerdergroep het verander. Geen soortgelyke groepe is vergelyk nie."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Bewyse en gekwalifiseerde gevolgtrekkings. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","afhl"],"metadata":{"term":2,"focus":"Bewyse en gekwalifiseerde gevolgtrekkings","language":"af","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=F_rQwUSTKoQ%3d&tabid=3205&portalid=0&mid=10756","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=mMkdIZmk3Ow%3d&tabid=570&portalid=0&mid=1555","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/afhl-12","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"84861860-9fdb-5f42-a55d-f8b4c7c6964b","title":"Afrikaans HL · Grade 12 · Term 3: Woordkeuse, weglating en visuele konteks","subject":"Afrikaans HL","grade":"Grade 12","questions":[{"question":"Wat is die effek van Lui in die opskrif?","options":["Dit raam die leerders negatief voordat hul omstandighede ondersoek is","Dit is 'n neutrale meting","Dit bewys elke leerder se motief","Dit gee vervoerdata"],"correct_index":0,"explanation":"Die gelaaide woord stuur die leser se oordeel sonder voldoende bewys van die leerders se redes.","stimulus":"Die opskrif lui: Lui leerders vermy leeslokaal. Die berig noem leë stoele, maar laat gesprekke met leerders sonder aandvervoer weg. Die foto is voor openingstyd geneem."},{"question":"Waarom is die foto se tydstip belangrik?","options":["Elke foto bewys die opskrif","Dit kan 'n misleidende indruk van bywoning gedurende oop ure skep","Tyd maak nooit saak nie","Dit vervang alle onderhoude"],"correct_index":1,"explanation":"'n Foto voor openingstyd toon nie noodwendig gebruik tydens bedryfsure nie. Konteks verander die interpretasie.","stimulus":"Die opskrif lui: Lui leerders vermy leeslokaal. Die berig noem leë stoele, maar laat gesprekke met leerders sonder aandvervoer weg. Die foto is voor openingstyd geneem."},{"question":"Watter weglating verswak die verklaring die meeste?","options":["Die stoele se handelsmerk","Die joernalis se gunstelingkleur","Leerders se verduidelikings van vervoerprobleme","Die muur se verfkode"],"correct_index":2,"explanation":"Die weglating hou direk verband met toegang en laat relevante ervarings buite die verklaring.","stimulus":"Die opskrif lui: Lui leerders vermy leeslokaal. Die berig noem leë stoele, maar laat gesprekke met leerders sonder aandvervoer weg. Die foto is voor openingstyd geneem."},{"question":"Watter opskrif is meer gebalanseerd?","options":["Alle leerders weier om te werk","Vervoer beïnvloed nooit bywoning nie","Leë stoele bewys luiheid","Leeslokaal se bywoning laat vrae oor toegang ontstaan"],"correct_index":3,"explanation":"Die herskrywing identifiseer 'n ondersoekbare probleem sonder om ongegronde blaam toe te ken.","stimulus":"Die opskrif lui: Lui leerders vermy leeslokaal. Die berig noem leë stoele, maar laat gesprekke met leerders sonder aandvervoer weg. Die foto is voor openingstyd geneem."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Woordkeuse, weglating en visuele konteks. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","afhl"],"metadata":{"term":3,"focus":"Woordkeuse, weglating en visuele konteks","language":"af","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=F_rQwUSTKoQ%3d&tabid=3205&portalid=0&mid=10756","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=mMkdIZmk3Ow%3d&tabid=570&portalid=0&mid=1555","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/afhl-12","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"e1a29cee-98dd-54cd-bb20-ea0b78b86b9a","title":"Afrikaans HL · Grade 12 · Term 4: Literêre argument en noukeurige lees","subject":"Afrikaans HL","grade":"Grade 12","questions":[{"question":"Watter besonderheid skep die duidelikste kontras?","options":["Die brief is gevou","Noma beweeg terug terwyl die ander vorentoe beweeg","Die trein is by 'n stasie","Daar is ander mense"],"correct_index":1,"explanation":"Die teenoorgestelde bewegings beklemtoon Noma se huiwering of afsonderlike keuse.","stimulus":"By die stasie vou Noma die brief weer oop. Die trein kom aan, ongeduldig en helder. Sy steek die brief in haar sak en tree terug van die perron se rand terwyl die ander vorentoe beweeg."},{"question":"Watter beeldspraak bevat die beskrywing van die trein as ongeduldig?","options":["Klanknabootsing","Letterlike verslag van 'n gesprek","Personifikasie","Rym"],"correct_index":2,"explanation":"Die trein kry 'n menslike eienskap, wat dringendheid skep en met Noma se huiwering kontrasteer.","stimulus":"By die stasie vou Noma die brief weer oop. Die trein kom aan, ongeduldig en helder. Sy steek die brief in haar sak en tree terug van die perron se rand terwyl die ander vorentoe beweeg."},{"question":"Watter interpretasie bly binne die teks se perke?","options":["Die brief bevat beslis 'n werksafwysing.","Noma het nog nooit gereis nie.","Al die reisigers ken die brief se inhoud.","Die herlees en terugtree suggereer onsekerheid oor vertrek."],"correct_index":3,"explanation":"Die teks gee leidrade van huiwering, maar verklap nie die brief se inhoud of Noma se hele geskiedenis nie.","stimulus":"By die stasie vou Noma die brief weer oop. Die trein kom aan, ongeduldig en helder. Sy steek die brief in haar sak en tree terug van die perron se rand terwyl die ander vorentoe beweeg."},{"question":"Watter sin verbind bewys en interpretasie die beste?","options":["Noma se terugtree teenoor die ander se voorwaartse beweging beklemtoon haar afsondering.","Alle stasies veroorsaak hartseer.","Die helder trein bewys die brief bevat goeie nuus.","Reis is altyd skadelik."],"correct_index":0,"explanation":"Die sterkste antwoord ontleed 'n spesifieke kontras en vermy ongegronde algemene stellings.","stimulus":"By die stasie vou Noma die brief weer oop. Die trein kom aan, ongeduldig en helder. Sy steek die brief in haar sak en tree terug van die perron se rand terwyl die ander vorentoe beweeg."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Literêre argument en noukeurige lees. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","afhl"],"metadata":{"term":4,"focus":"Literêre argument en noukeurige lees","language":"af","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=F_rQwUSTKoQ%3d&tabid=3205&portalid=0&mid=10756","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=mMkdIZmk3Ow%3d&tabid=570&portalid=0&mid=1555","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/afhl-12","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"910d2097-d7a6-5021-b20f-c981f7eb357c","title":"isiXhosa HL · Grade 12 · Term 2: Ubungqina, uthelekiso nezigqibo","subject":"isiXhosa HL","grade":"Grade 12","questions":[{"question":"Leliphi ibango elifuna ukuhlolwa?","options":["Iiyure ezinde kuphela zibangele ukwanda.","Ingxelo ichaza ukwanda nge-20%.","Kwangeniswa iincwadi ezintsha.","Kwaqalwa iklabhu yokufunda."],"correct_index":0,"explanation":"Zininzi izinto ezitshintshileyo ngaxeshanye. Ukubona ukwanda emva kotshintsho akungqini ukuba yinto enye kuphela ebangeleyo.","stimulus":"Ingxelo ithi ukusetyenziswa kwethala kunyuke nge-20% emva kokwandiswa kweeyure. Kwangelo xesha kwangeniswa iincwadi ezintsha kwaza kwaqalwa iklabhu yokufunda. Ingxelo ithi iiyure ezinde kuphela zenze olu tshintsho."},{"question":"Sesiphi isigqibo esilumkileyo?","options":["Iincwadi ezintsha azinakuba naliphi ifuthe.","Ukusetyenziswa kunyukile, kodwa indima yotshintsho ngalunye ayikacaci.","Iklabhu ngokuqinisekileyo yehlise ukusetyenziswa.","Iiyure azinakuchaphazela ukufikelela."],"correct_index":1,"explanation":"Isigqibo siyavuma oko ingxelo ikulinganisileyo size singagqithisi kubungqina obukhoyo.","stimulus":"Ingxelo ithi ukusetyenziswa kwethala kunyuke nge-20% emva kokwandiswa kweeyure. Kwangelo xesha kwangeniswa iincwadi ezintsha kwaza kwaqalwa iklabhu yokufunda. Ingxelo ithi iiyure ezinde kuphela zenze olu tshintsho."},{"question":"Luluphi ulwazi olunceda ukutolika i-20%?","options":["Umbala wophahla kuphela.","Igama lenkampani epeyintileyo kuphela.","Inani lokuqala labasebenzisi nendlela ababalwe ngayo.","Ubude besihloko kuphela."],"correct_index":2,"explanation":"Ukwanda ngepesenti kufuna isiseko nenani elithelekiswayo. Indlela yokubala ichaphazela ukuthembeka kwengxelo.","stimulus":"Ingxelo ithi ukusetyenziswa kwethala kunyuke nge-20% emva kokwandiswa kweeyure. Kwangelo xesha kwangeniswa iincwadi ezintsha kwaza kwaqalwa iklabhu yokufunda. Ingxelo ithi iiyure ezinde kuphela zenze olu tshintsho."},{"question":"Igama kuphela linegalelo lini kwibango?","options":["Libonisa ukungaqiniseki okufanelekileyo.","Lithetha ukuba kukho izizathu ezininzi.","Lisusa naluphi na uthelekiso.","Lenza ibango lobangela libe ngqongqo kakhulu."],"correct_index":3,"explanation":"Kuphela likhupha ezinye iinkcazelo. Elo bango lifuna ubungqina obomeleleyo bokwahlula ifuthe lezinye izinto.","stimulus":"Ingxelo ithi ukusetyenziswa kwethala kunyuke nge-20% emva kokwandiswa kweeyure. Kwangelo xesha kwangeniswa iincwadi ezintsha kwaza kwaqalwa iklabhu yokufunda. Ingxelo ithi iiyure ezinde kuphela zenze olu tshintsho."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Ubungqina, uthelekiso nezigqibo. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","xhhl"],"metadata":{"term":2,"focus":"Ubungqina, uthelekiso nezigqibo","language":"xh","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=sJ87UYZMguI%3d&tabid=3205&portalid=0&mid=10756","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=QsGQeCZMUxo%3d&tabid=570&portalid=0&mid=1555","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/xhhl-12","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"58869dae-6341-54b3-84b1-316b97ec12fb","title":"isiXhosa HL · Grade 12 · Term 3: Ukukhethwa kwamagama nokushiywa kolwazi","subject":"isiXhosa HL","grade":"Grade 12","questions":[{"question":"Liliphi ifuthe legama abangamavila?","options":["Linika umlinganiselo ocacileyo wexesha.","Likhokela isigwebo esibi ngaphambi kokuhlolwa kweemeko.","Liqinisekisa ukuba wonke umfundi uyaxoka.","Lichaza indawo yethala kuphela."],"correct_index":1,"explanation":"Igama linomthwalo wovakalelo kwaye libeka ityala ngaphandle kobungqina obaneleyo bezizathu zabafundi.","stimulus":"Isihloko sithi: Abafundi abangamavila abalisebenzisi ithala. Ifoto yezitulo ezingenabantu yathathwa ngaphambi kokuvulwa. Ingxelo ayiquki amazwi abafundi abangenazithuthi emva kwemini."},{"question":"Kutheni ixesha lokuthathwa kwefoto libalulekile?","options":["Zonke iifoto zingqina zonke izihloko.","Ixesha alinakuchaphazela intsingiselo.","Ifoto yangaphambi kokuvulwa ayingqini ukusetyenziswa ngexesha lokusebenza.","Ifoto ibonisa onke amava abafundi."],"correct_index":2,"explanation":"Umfanekiso ufuna umxholo wexesha nendawo. Ngaphandle kwawo, unokunika umfanekiso olahlekisayo.","stimulus":"Isihloko sithi: Abafundi abangamavila abalisebenzisi ithala. Ifoto yezitulo ezingenabantu yathathwa ngaphambi kokuvulwa. Ingxelo ayiquki amazwi abafundi abangenazithuthi emva kwemini."},{"question":"Loluphi ulwazi olushiyiweyo olubalulekileyo?","options":["Inkampani eyenze izitulo.","Umbala wepeni yentatheli.","Ubukhulu belogo yethala.","Amava abafundi abanengxaki yokuthutha."],"correct_index":3,"explanation":"Ukuthutha kuchaphazela ukufikelela ngqo. Ukushiya elo lizwi ngaphandle kunokwenza ingxelo ingalingani.","stimulus":"Isihloko sithi: Abafundi abangamavila abalisebenzisi ithala. Ifoto yezitulo ezingenabantu yathathwa ngaphambi kokuvulwa. Ingxelo ayiquki amazwi abafundi abangenazithuthi emva kwemini."},{"question":"Sesiphi isihloko esilungelelanisiweyo?","options":["Ukusetyenziswa kwethala kuvusa imibuzo ngokufikelela.","Bonke abafundi bayakwala ukufunda.","Izitulo ezingenabantu zingqina ubuvila.","Ukuthutha akuchaphazeli mntu."],"correct_index":0,"explanation":"Isihloko sikhomba umba onokuphandwa ngaphandle kokugweba abantu ngezizathu ezingekahlolwa.","stimulus":"Isihloko sithi: Abafundi abangamavila abalisebenzisi ithala. Ifoto yezitulo ezingenabantu yathathwa ngaphambi kokuvulwa. Ingxelo ayiquki amazwi abafundi abangenazithuthi emva kwemini."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Ukukhethwa kwamagama nokushiywa kolwazi. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","xhhl"],"metadata":{"term":3,"focus":"Ukukhethwa kwamagama nokushiywa kolwazi","language":"xh","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=sJ87UYZMguI%3d&tabid=3205&portalid=0&mid=10756","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=QsGQeCZMUxo%3d&tabid=570&portalid=0&mid=1555","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/xhhl-12","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"6667eba0-1641-56ac-b926-67a8cf80b26f","title":"isiXhosa HL · Grade 12 · Term 4: Uhlalutyo loncwadi olusondele kumbhalo","subject":"isiXhosa HL","grade":"Grade 12","questions":[{"question":"Yeyiphi inkcukacha eyakha umahluko ocacileyo?","options":["Ileta ikhona kuphela.","Uloliwe usebenzisa isiporo.","UNoma ubuya umva ngoxa abanye besiya phambili.","Kukho abantu esitishini."],"correct_index":2,"explanation":"Iintshukumo ezichaseneyo zigxininisa ukwahluka kwesigqibo okanye ukungaqiniseki kukaNoma.","stimulus":"Esitishini uNoma uvula ileta kwakhona. Uloliwe uyangena, ungxamile kwaye uqaqambile. Ufaka ileta epokothweni abuye umva, ngoxa abanye besiya phambili."},{"question":"Ukuchaza uloliwe njengongxamileyo ngumzekelo wantoni?","options":["Weresiphi","Woluhlu lwamaxabiso","Wemiyalelo yokwakha","Wesimntwiso"],"correct_index":3,"explanation":"Uloliwe unikwa uphawu oluqhele ukunxulunyaniswa nomntu. Oku kunokwenza indawo ivakale icinezela okanye ingxamile.","stimulus":"Esitishini uNoma uvula ileta kwakhona. Uloliwe uyangena, ungxamile kwaye uqaqambile. Ufaka ileta epokothweni abuye umva, ngoxa abanye besiya phambili."},{"question":"Sesiphi isigqibo esigcina umda wesicatshulwa?","options":["Ukuvula ileta kwakhona nokubuya umva kunokubonisa ukungaqiniseki ngokuhamba.","Ileta ngokuqinisekileyo iyamgxotha emsebenzini.","UNoma akazange akhwele uloliwe.","Wonke umntu uyawazi umxholo weleta."],"correct_index":0,"explanation":"Isicatshulwa sinika imikhondo yezenzo, kodwa asisixeleli umxholo weleta okanye yonke imbali yomlinganiswa.","stimulus":"Esitishini uNoma uvula ileta kwakhona. Uloliwe uyangena, ungxamile kwaye uqaqambile. Ufaka ileta epokothweni abuye umva, ngoxa abanye besiya phambili."},{"question":"Sesiphi isivakalisi esidibanisa ubungqina nokutolika?","options":["Zonke izitishi zenza abantu balile.","Ukubuya umva kukaNoma xa abanye besiya phambili kugxininisa ukuba wahlukene nabo.","Ukukhanya kukaloliwe kungqina iindaba ezimnandi.","Ukuhamba kusoloko kuyingozi."],"correct_index":1,"explanation":"Uhlalutyo olomeleleyo lubhekisa kwinkcukacha ethile luze luchaze umsebenzi wayo, lungaxhomekeki kwibango eliphangaleleyo.","stimulus":"Esitishini uNoma uvula ileta kwakhona. Uloliwe uyangena, ungxamile kwaye uqaqambile. Ufaka ileta epokothweni abuye umva, ngoxa abanye besiya phambili."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Uhlalutyo loncwadi olusondele kumbhalo. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","xhhl"],"metadata":{"term":4,"focus":"Uhlalutyo loncwadi olusondele kumbhalo","language":"xh","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=sJ87UYZMguI%3d&tabid=3205&portalid=0&mid=10756","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=QsGQeCZMUxo%3d&tabid=570&portalid=0&mid=1555","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/xhhl-12","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"2d3d04dc-f548-50a4-aa55-4b34481d63a2","title":"isiZulu HL · Grade 12 · Term 2: Ubufakazi, ukuqhathanisa neziphetho","subject":"isiZulu HL","grade":"Grade 12","questions":[{"question":"Yisiphi isimangalo esidinga ukuhlolwa?","options":["Umbiko uchaza ukwanda ngo-20%.","Amahora andisiwe kuphela abangele ukwanda.","Kwafakwa izincwadi ezintsha.","Kwaqalwa iklabhu yokufunda."],"correct_index":1,"explanation":"Izinto eziningi zishintshe ngesikhathi esisodwa. Ukuhambisana kwezinto akufakazeli imbangela eyodwa kuphela.","stimulus":"Umbiko uthi ukusetshenziswa komtapo kukhuphuke ngo-20% ngemva kokwandiswa kwamahora. Ngaleso sikhathi kwafakwa izincwadi ezintsha kwaqalwa neklabhu yokufunda. Umbiko uthi amahora andisiwe kuphela adale ushintsho."},{"question":"Yisiphi isiphetho esicophelelayo?","options":["Izincwadi ezintsha azinakuba nomthelela.","Iklabhu yehlise ukusetshenziswa nakanjani.","Ukusetshenziswa kukhuphukile, kodwa indima yoshintsho ngalunye ayikacaci.","Amahora awakwazi ukuthinta ukufinyelela."],"correct_index":2,"explanation":"Isiphetho samukela okukaliwe kodwa asigabadeli ubufakazi obukhona.","stimulus":"Umbiko uthi ukusetshenziswa komtapo kukhuphuke ngo-20% ngemva kokwandiswa kwamahora. Ngaleso sikhathi kwafakwa izincwadi ezintsha kwaqalwa neklabhu yokufunda. Umbiko uthi amahora andisiwe kuphela adale ushintsho."},{"question":"Yiluphi ulwazi olusiza ukuqonda u-20%?","options":["Umbala wophahla kuphela.","Igama lenkampani ependile kuphela.","Ubude besihloko kuphela.","Inani lokuqala labasebenzisi nendlela ababalwe ngayo."],"correct_index":3,"explanation":"Iphesenti lokwanda lidinga isisekelo sokuqhathanisa. Indlela yokubala ibalulekile ekuthembekeni kombiko.","stimulus":"Umbiko uthi ukusetshenziswa komtapo kukhuphuke ngo-20% ngemva kokwandiswa kwamahora. Ngaleso sikhathi kwafakwa izincwadi ezintsha kwaqalwa neklabhu yokufunda. Umbiko uthi amahora andisiwe kuphela adale ushintsho."},{"question":"Igama kuphela liyiguqula kanjani incazelo?","options":["Lenza isimangalo sembangela sibe namandla kakhulu.","Lisho ukuthi kunezizathu eziningi.","Liveza ukungaqiniseki okuningi.","Lisusa zonke izidingo zobufakazi."],"correct_index":0,"explanation":"Kuphela likhipha ezinye izincazelo. Lokho kudinga ubufakazi obuqinile obuhlukanisa imithelela yezinye izinto.","stimulus":"Umbiko uthi ukusetshenziswa komtapo kukhuphuke ngo-20% ngemva kokwandiswa kwamahora. Ngaleso sikhathi kwafakwa izincwadi ezintsha kwaqalwa neklabhu yokufunda. Umbiko uthi amahora andisiwe kuphela adale ushintsho."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Ubufakazi, ukuqhathanisa neziphetho. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","zuhl"],"metadata":{"term":2,"focus":"Ubufakazi, ukuqhathanisa neziphetho","language":"zu","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=72xm6LEbf4o%3d&tabid=3205&portalid=0&mid=10756","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=nZlas4HGdYI%3d&tabid=570&portalid=0&mid=1555","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/zuhl-12","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"6ae04159-dc31-5118-b382-17b118764071","title":"isiZulu HL · Grade 12 · Term 3: Ukukhethwa kwamagama nokushiywa kolwazi","subject":"isiZulu HL","grade":"Grade 12","questions":[{"question":"Igama abangamavila linamuphi umthelela?","options":["Linikeza isilinganiso esicacile sesikhathi.","Lifakazela ukuthi wonke umfundi uqamba amanga.","Liholela esahlulelweni esibi ngaphambi kokuhlola izimo.","Lichaza indawo yomtapo kuphela."],"correct_index":2,"explanation":"Leli gama lithwele umuzwa wokugxeka ngaphandle kobufakazi obanele bezizathu zabafundi.","stimulus":"Isihloko sithi: Abafundi abangamavila abawusebenzisi umtapo. Isithombe sezihlalo ezingenabantu sathathwa ngaphambi kokuvula. Umbiko awuwafaki amazwi abafundi abangenazo izinto zokuthutha ntambama."},{"question":"Kungani isikhathi sesithombe sibalulekile?","options":["Zonke izithombe zifakazela zonke izihloko.","Isikhathi asiyithinti incazelo.","Isithombe siveza wonke amava abafundi.","Esangaphambi kokuvula asifakazeli ukusetshenziswa ngesikhathi sokusebenza."],"correct_index":3,"explanation":"Isithombe sidinga umongo wesikhathi nendawo ukuze singadukisi abafundi.","stimulus":"Isihloko sithi: Abafundi abangamavila abawusebenzisi umtapo. Isithombe sezihlalo ezingenabantu sathathwa ngaphambi kokuvula. Umbiko awuwafaki amazwi abafundi abangenazo izinto zokuthutha ntambama."},{"question":"Yiluphi ulwazi olushiywe ngaphandle olubalulekile?","options":["Amava abafundi abanezinkinga zokuthutha.","Inkampani eyakha izihlalo.","Umbala wepeni lentatheli.","Ubukhulu belogo yomtapo."],"correct_index":0,"explanation":"Ezokuthutha zithinta ukufinyelela ngqo. Ukushiya lawo mazwi ngaphandle kungenza umbiko ungalingani.","stimulus":"Isihloko sithi: Abafundi abangamavila abawusebenzisi umtapo. Isithombe sezihlalo ezingenabantu sathathwa ngaphambi kokuvula. Umbiko awuwafaki amazwi abafundi abangenazo izinto zokuthutha ntambama."},{"question":"Yisiphi isihloko esilinganiselayo?","options":["Bonke abafundi bayenqaba ukufunda.","Ukusetshenziswa komtapo kuvusa imibuzo ngokufinyelela.","Izihlalo ezingenabantu zifakazela ubuvila.","Ezokuthutha azithinti muntu."],"correct_index":1,"explanation":"Isihloko sikhomba umbuzo ongaphenywa ngaphandle kokwahlulela izizathu zabantu ezingakahlolwa.","stimulus":"Isihloko sithi: Abafundi abangamavila abawusebenzisi umtapo. Isithombe sezihlalo ezingenabantu sathathwa ngaphambi kokuvula. Umbiko awuwafaki amazwi abafundi abangenazo izinto zokuthutha ntambama."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Ukukhethwa kwamagama nokushiywa kolwazi. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","zuhl"],"metadata":{"term":3,"focus":"Ukukhethwa kwamagama nokushiywa kolwazi","language":"zu","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=72xm6LEbf4o%3d&tabid=3205&portalid=0&mid=10756","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=nZlas4HGdYI%3d&tabid=570&portalid=0&mid=1555","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/zuhl-12","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}},{"id":"380ab904-d0eb-5141-928c-a4b5e4fc3814","title":"isiZulu HL · Grade 12 · Term 4: Ukuhlaziya izincwadi ngokufunda ngokujulile","subject":"isiZulu HL","grade":"Grade 12","questions":[{"question":"Yimuphi umniningwane owakha umehluko ocacile?","options":["Incwadi ikhona kuphela.","Isitimela sisebenzisa ujantshi.","Kunabantu esiteshini.","UNoma uyahlehla kuyilapho abanye beya phambili."],"correct_index":3,"explanation":"Izenzo eziphikisanayo zingagcizelela ukwehluka kwesinqumo noma ukungaqiniseki kukaNoma.","stimulus":"Esiteshini uNoma uvula incwadi futhi. Isitimela siyangena, sixhamazela futhi sikhanya. Ufaka incwadi ephaketheni ahlehle, kuyilapho abanye beya phambili."},{"question":"Ukuchaza isitimela njengesisxhamazelayo kuyini?","options":["Ukwenza samuntu","Iresiphi","Uhlu lwamanani","Imiyalelo yokwakha"],"correct_index":0,"explanation":"Isitimela sinikwa isici somuntu. Lokhu kungadala umuzwa wokuphuthuma ohlukile ekungabazeni kukaNoma.","stimulus":"Esiteshini uNoma uvula incwadi futhi. Isitimela siyangena, sixhamazela futhi sikhanya. Ufaka incwadi ephaketheni ahlehle, kuyilapho abanye beya phambili."},{"question":"Yisiphi isiphetho esigcina imikhawulo yombhalo?","options":["Incwadi imxosha emsebenzini ngokuqinisekile.","Ukuvula incwadi futhi nokuhlehla kungasikisela ukungaqiniseki ngokuhamba.","UNoma akakaze agibele isitimela.","Bonke abantu bayakwazi okubhalwe encwadini."],"correct_index":1,"explanation":"Umbhalo unikeza izinkomba kodwa awukuvezi okuqukethwe incwadi noma wonke umlando womlingiswa.","stimulus":"Esiteshini uNoma uvula incwadi futhi. Isitimela siyangena, sixhamazela futhi sikhanya. Ufaka incwadi ephaketheni ahlehle, kuyilapho abanye beya phambili."},{"question":"Yimuphi umusho oxhumanisa ubufakazi nencazelo?","options":["Zonke iziteshi zenza abantu bakhale.","Ukukhanya kwesitimela kufakazela izindaba ezinhle.","Ukuhlehla kukaNoma lapho abanye beya phambili kugcizelela ukwehluka kwakhe kubo.","Ukuhamba kuhlala kuyingozi."],"correct_index":2,"explanation":"Ukuhlaziya okuqinile kubhekisa emininingwaneni ethile kuchaze umsebenzi wayo ngaphandle kwesimangalo esibanzi esingenabufakazi.","stimulus":"Esiteshini uNoma uvula incwadi futhi. Isitimela siyangena, sixhamazela futhi sikhanya. Ufaka incwadi ephaketheni ahlehle, kuyilapho abanye beya phambili."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Ukuhlaziya izincwadi ngokufunda ngokujulile. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":4,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","zuhl"],"metadata":{"term":4,"focus":"Ukuhlaziya izincwadi ngokufunda ngokujulile","language":"zu","content_version":"2026-10-21.1","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=72xm6LEbf4o%3d&tabid=3205&portalid=0&mid=10756","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=nZlas4HGdYI%3d&tabid=570&portalid=0&mid=1555","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/zuhl-12","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content."}}]$smartbridge$::jsonb)
